#!/usr/bin/env node
// Refreshes the vendored ClarkCant manifests in fixtures/upstream/clarkcant/ from a ClarkCant checkout and rewrites
// UPSTREAM.json with the commit they came from and the sha256 of every file.
//
//   node scripts/sync-clarkcant-fixtures.mjs --from ../clarkcant
//
// Reference manifests are read from the checkout's HEAD commit (`git show`), never from its working tree, so the
// recorded commit is exactly what was copied. The blank template is generated by running the checkout's own CLI
// (`clark widget init --template blank`), which needs the checkout's dependencies installed (`pnpm install` there)
// and refuses to run when the CLI or contract sources have uncommitted changes.
//
// The script also records the sha256 of ClarkCant's manifest contract sources. When they change, it prints which
// ones did: review packages/contracts/src/manifest.ts against them before committing the refreshed fixtures.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, posix, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const fixturesDir = join(root, "fixtures", "upstream", "clarkcant");
const upstreamFile = join(fixturesDir, "UPSTREAM.json");

/** The files ClarkCant's manifest contract lives in. Hashed, not vendored: they are what the mirror is reviewed against. */
const CONTRACT_SOURCES = [
  "packages/contracts/src/install.ts",
  "packages/contracts/src/primitives.ts",
  "packages/contracts/src/grants.ts",
  "packages/contracts/src/network-origin.ts",
  "packages/contracts/src/browser-token.ts",
  "packages/contracts/src/service-egress.ts",
  "packages/contracts/src/service-connection.ts",
  "packages/contracts/src/service-artifacts.ts",
  "packages/contracts/src/resource-profiles.ts",
  "packages/core/src/widget-package.ts",
];
/** Working-tree paths the blank template is generated from; they must match HEAD. */
const GENERATOR_PATHS = ["packages/widget-cli", "packages/contracts", "packages/core"];
const BLANK_COMMAND = ["packages/widget-cli/src/cli.ts", "widget", "init", "<tmp>/my-widget", "--template", "blank"];

function fail(message) {
  console.error(`sync-clarkcant-fixtures: ${message}`);
  process.exit(1);
}

function parseArgs(argv) {
  const index = argv.indexOf("--from");
  const from = index === -1 ? undefined : argv[index + 1];
  if (!from) fail("usage: node scripts/sync-clarkcant-fixtures.mjs --from <path to a ClarkCant checkout>");
  return { from: resolve(from) };
}

function git(checkout, args) {
  return execFileSync("git", ["-C", checkout, ...args], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
}

/** Line endings are normalised so a checkout with CRLF conversion hashes the same as the commit. */
function normalise(text) {
  return text.replace(/\r\n/g, "\n");
}

function sha256(text) {
  return createHash("sha256").update(text, "utf8").digest("hex");
}

function repositoryOf(checkout) {
  const url = git(checkout, ["remote", "get-url", "origin"]).trim();
  const match = /github\.com[:/]([^/]+\/[^/]+?)(?:\.git)?$/.exec(url);
  return match ? match[1] : url;
}

function generateBlankTemplate(checkout) {
  const dirty = git(checkout, ["status", "--porcelain", "--", ...GENERATOR_PATHS]).trim();
  if (dirty) fail(`the checkout has uncommitted changes the CLI would run with:\n${dirty}`);
  const tmp = mkdtempSync(join(tmpdir(), "clarkcant-blank-"));
  try {
    const target = join(tmp, "my-widget");
    const args = BLANK_COMMAND.map((arg) => (arg === "<tmp>/my-widget" ? target : arg));
    try {
      execFileSync(process.execPath, args, { cwd: checkout, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
    } catch (error) {
      const stderr = typeof error?.stderr === "string" ? error.stderr.trim() : "";
      fail(`the ClarkCant CLI could not create the blank template (run \`pnpm install\` in the checkout first)\n${stderr}`);
    }
    return normalise(readFileSync(join(target, "clarkcant.json"), "utf8"));
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
}

function main() {
  const { from } = parseArgs(process.argv.slice(2));
  if (!existsSync(join(from, "packages", "contracts", "src", "install.ts"))) {
    fail(`${from} does not look like a ClarkCant checkout (no packages/contracts/src/install.ts)`);
  }
  const commit = git(from, ["rev-parse", "HEAD"]).trim();
  const show = (path) => normalise(git(from, ["show", `${commit}:${path}`]));

  const referenceApps = git(from, ["ls-tree", "-r", "--name-only", commit, "--", "examples/reference-apps"])
    .split("\n")
    .filter((path) => /^examples\/reference-apps\/[^/]+\/clarkcant\.json$/.test(path))
    .sort();
  if (referenceApps.length === 0) fail(`commit ${commit} has no examples/reference-apps/*/clarkcant.json`);

  const files = referenceApps.map((source) => ({
    path: posix.join("reference-apps", source.split("/")[2], "clarkcant.json"),
    source,
    content: show(source),
  }));
  files.push({
    path: "templates/blank/clarkcant.json",
    source: `generated: node ${BLANK_COMMAND.join(" ")}`,
    content: generateBlankTemplate(from),
  });
  for (const file of files) {
    try {
      JSON.parse(file.content);
    } catch {
      fail(`${file.source} is not valid JSON`);
    }
  }

  const previous = existsSync(upstreamFile) ? JSON.parse(readFileSync(upstreamFile, "utf8")) : null;
  const contractSources = CONTRACT_SOURCES.map((source) => ({ source, sha256: sha256(show(source)) }));

  for (const entry of ["reference-apps", "templates"]) rmSync(join(fixturesDir, entry), { recursive: true, force: true });
  for (const file of files) {
    const target = join(fixturesDir, ...file.path.split("/"));
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, file.content);
  }
  const upstream = {
    repository: repositoryOf(from),
    commit,
    note: "Generated by scripts/sync-clarkcant-fixtures.mjs. Do not edit by hand; `pnpm contract:check` verifies it.",
    files: files.map(({ path, source, content }) => ({ path, source, sha256: sha256(content) })),
    contractSources,
  };
  writeFileSync(upstreamFile, `${JSON.stringify(upstream, null, 2)}\n`);

  console.info(`synced ${files.length} manifests from ${upstream.repository}@${commit}`);
  if (previous) {
    const before = new Map((previous.contractSources ?? []).map((entry) => [entry.source, entry.sha256]));
    const changed = contractSources.filter((entry) => before.get(entry.source) !== entry.sha256).map((entry) => entry.source);
    if (changed.length > 0) {
      console.warn(
        `ClarkCant's manifest contract changed since ${previous.commit}:\n  ${changed.join("\n  ")}\n` +
          "Review packages/contracts/src/manifest.ts against these files before committing.",
      );
    }
  }
  console.info("next: pnpm contract:check");
}

main();
